import { CliExit, parseCommandLine } from "./lib/cli.mjs";
import { convertBits, decodeSegwitAddress } from "./lib/bech32/segwit.mjs";
import { formatPythonValue } from "./lib/format.mjs";

function main() {
  const args = parseCommandLine(process.argv.slice(2), process.argv[1]);
  const decoded = decodeSegwitAddress(args.a, args.b);

  if (decoded[0] !== null && decoded[1] !== null) {
    const [witver, witprog] = decoded;
    const converted = convertBits(witprog, 5, 8);

    process.stdout.write(`${formatPythonValue(witver)}\n`);
    process.stdout.write(`${formatPythonValue(converted)}\n`);
  }
}

try {
  main();
} catch (error) {
  if (error instanceof CliExit) {
    const stream = error.stream === "stdout" ? process.stdout : process.stderr;
    stream.write(error.message);
    process.exit(error.code);
  }

  throw error;
}

