class CliExit extends Error {
  constructor(code, stream, message) {
    super(message);
    this.code = code;
    this.stream = stream;
    this.message = message;
  }
}

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;

function basename(path) {
  if (!path) {
    return "test12.mjs";
  }

  const normalized = path.replace(/\\/g, "/");
  const parts = normalized.split("/");
  return parts[parts.length - 1] || "test12.mjs";
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function help(programName) {
  return `${usage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function formatMissingRequired(programName, missing) {
  return `${usage(programName)}\n${programName}: error: the following arguments are required: ${missing.join(", ")}\n`;
}

function formatExpectedArgument(programName, option) {
  return `${usage(programName)}\n${programName}: error: argument ${option}: expected one argument\n`;
}

function formatUnrecognized(programName, extras) {
  return `${usage(programName)}\n${programName}: error: unrecognized arguments: ${extras.join(" ")}\n`;
}

function isNegativeNumberLike(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function isKnownOptionToken(token) {
  return (
    token === "-h" ||
    token === "--help" ||
    token === "--" ||
    token === "--a" ||
    token === "--b" ||
    token.startsWith("--a=") ||
    token.startsWith("--b=")
  );
}

function shouldRejectAsMissingValue(token) {
  return token === undefined || (token.startsWith("-") && !isNegativeNumberLike(token));
}

export { CliExit };

export function parseCommandLine(argv, scriptPath) {
  const programName = basename(scriptPath);
  const values = { a: undefined, b: undefined };
  const extras = [];
  let optionParsingEnded = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (!optionParsingEnded && (token === "-h" || token === "--help")) {
      throw new CliExit(0, "stdout", help(programName));
    }

    if (!optionParsingEnded && token === "--") {
      optionParsingEnded = true;
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (!optionParsingEnded && (token === "--a" || token === "--b")) {
      const next = argv[index + 1];
      if (shouldRejectAsMissingValue(next)) {
        throw new CliExit(2, "stderr", formatExpectedArgument(programName, token));
      }

      values[token.slice(2)] = next;
      index += 1;
      continue;
    }

    if (!optionParsingEnded && token.startsWith("--a=")) {
      values.a = token.slice(4);
      continue;
    }

    if (!optionParsingEnded && token.startsWith("--b=")) {
      values.b = token.slice(4);
      continue;
    }

    if (!optionParsingEnded && token.startsWith("-") && !isNegativeNumberLike(token)) {
      extras.push(token);

      const next = argv[index + 1];
      if (next !== undefined && (!isKnownOptionToken(next) || isNegativeNumberLike(next))) {
        extras.push(next);
        index += 1;
      }

      continue;
    }

    extras.push(token);
