  if (values.a === undefined) {
    missing.push("--a");
  }
  if (values.b === undefined) {
    missing.push("--b");
  }

  if (missing.length > 0) {
    throw new CliExit(2, "stderr", formatMissingRequired(programName, missing));
  }

  if (extras.length > 0) {
    throw new CliExit(2, "stderr", formatUnrecognized(programName, extras));
  }

  return values;
