export function decodeSegwitAddress(hrp, address) {
  const [decodedHrp, data] = decodeBech32(address);
  if (decodedHrp === null || data === null || decodedHrp !== hrp) {
    return [null, null];
  }

  if (data.length === 0) {
    return [null, null];
  }

  const witnessVersion = data[0];
  const witnessProgram = convertBits(data.slice(1), 5, 8, false);

  if (witnessProgram === null) {
    return [null, null];
  }

  if (witnessVersion > 16) {
    return [null, null];
  }

  if (witnessProgram.length < 2 || witnessProgram.length > 40) {
    return [null, null];
  }

  if (witnessVersion === 0 && witnessProgram.length !== 20 && witnessProgram.length !== 32) {
    return [null, null];
  }

  return [witnessVersion, witnessProgram];
}

