const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const GENERATOR = [
  0x3b6a57b2,
  0x26508e6d,
  0x1ea119fa,
  0x3d4233dd,
  0x2a1462b3,
];

function bech32Polymod(values) {
  let checksum = 1;

  for (const value of values) {
    const top = checksum >> 25;
    checksum = ((checksum & 0x1ffffff) << 5) ^ value;

    for (let bit = 0; bit < GENERATOR.length; bit += 1) {
      if ((top >> bit) & 1) {
        checksum ^= GENERATOR[bit];
      }
    }
  }

  return checksum;
}

function hrpExpand(hrp) {
  const expanded = [];

  for (let index = 0; index < hrp.length; index += 1) {
    expanded.push(hrp.charCodeAt(index) >> 5);
  }

  expanded.push(0);

  for (let index = 0; index < hrp.length; index += 1) {
    expanded.push(hrp.charCodeAt(index) & 31);
  }

  return expanded;
}

function verifyChecksum(hrp, data) {
  return bech32Polymod(hrpExpand(hrp).concat(data)) === 1;
}

export function decodeBech32(bechString) {
  if (bechString.length > 90) {
    return [null, null];
  }

  let hasLower = false;
  let hasUpper = false;

  for (let index = 0; index < bechString.length; index += 1) {
    const code = bechString.charCodeAt(index);
    if (code < 33 || code > 126) {
      return [null, null];
    }
    if (code >= 97 && code <= 122) {
      hasLower = true;
    } else if (code >= 65 && code <= 90) {
      hasUpper = true;
    }
  }

  if (hasLower && hasUpper) {
    return [null, null];
  }

  const normalized = bechString.toLowerCase();
  const separator = normalized.lastIndexOf("1");

  if (separator < 1 || separator + 7 > normalized.length) {
    return [null, null];
  }

  const hrp = normalized.slice(0, separator);
  const data = [];

  for (let index = separator + 1; index < normalized.length; index += 1) {
    const value = CHARSET.indexOf(normalized[index]);
    if (value === -1) {
      return [null, null];
    }
    data.push(value);
  }

  if (!verifyChecksum(hrp, data)) {
    return [null, null];
  }

  return [hrp, data.slice(0, -6)];
}

export function convertBits(data, fromBits, toBits, pad = true) {
  let accumulator = 0;
  let bits = 0;
  const converted = [];
  const maxValue = (1 << toBits) - 1;
  const maxAccumulator = (1 << (fromBits + toBits - 1)) - 1;

  for (const value of data) {
    if (value < 0 || value >> fromBits) {
      return null;
    }

    accumulator = ((accumulator << fromBits) | value) & maxAccumulator;
    bits += fromBits;

    while (bits >= toBits) {
      bits -= toBits;
      converted.push((accumulator >> bits) & maxValue);
    }
  }

  if (pad) {
    if (bits > 0) {
      converted.push((accumulator << (toBits - bits)) & maxValue);
    }
  } else if (bits >= fromBits || ((accumulator << (toBits - bits)) & maxValue) !== 0) {
    return null;
  }

  return converted;
}

